def newId(self, used=None):
        """returns an unused ruleset id. This is not multi user safe."""
        if used is not None:
            self.__used = used
        data = Query("select max(id)+1 from %s" % self.rulesetTable()).data
        try:
            return int(data[0][0])
        except ValueError:
            return 1

